// The HTTP request Workly sends to deliver the task, as it would be sent
// now: the task's own headers plus Workly's (`Workly-Task-Id`,
// `Workly-Signature`, ...), and the exact body. The signature is fresh,
// so replaying the request (for example with curl) while fixing an
// endpoint passes verification until the timestamp is too old. Nothing
// is sent and the task doesn't change. `Workly-Attempt` is the next
// attempt for a pending task, otherwise the latest.
//
// Returns a wrapper object for the known response body format(s).
//
// Corresponds with GET /v1/tasks/{id}/delivery (the `GetTaskDelivery` operationId).
func (c *ClientWithResponses) GetTaskDeliveryWithResponse(ctx context.Context, id TaskID, reqEditors ...RequestEditorFn) (*GetTaskDeliveryResponse, error) {
	rsp, err := c.GetTaskDelivery(ctx, id, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseGetTaskDeliveryResponse(rsp)
}

// RetryTaskWithResponse Retry a task now
//
// Makes the task due now. A succeeded, failed or cancelled task is
// replayed with a fresh set of `max_attempts`; its attempt numbers keep
// counting. A pending task (scheduled or waiting to retry) just runs
// sooner. A task can't be retried while an attempt is in flight
// (`invalid_state`).
//
// Returns a wrapper object for the known response body format(s).
//
// Corresponds with POST /v1/tasks/{id}/retry (the `RetryTask` operationId).
func (c *ClientWithResponses) RetryTaskWithResponse(ctx context.Context, id TaskID, reqEditors ...RequestEditorFn) (*RetryTaskResponse, error) {
	rsp, err := c.RetryTask(ctx, id, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseRetryTaskResponse(rsp)
}

